"use client";

import { useApi } from "./useApi";
import { Product } from "@/types";
import { useQuery } from "@tanstack/react-query";

export const useProducts = () => {
  const api = useApi();

  return useQuery({
    queryKey: ["products"],
    queryFn: async () => {
      const { data } = await api.get<Product[]>("/products/");
      return data;
    },
  });
};
