"use client";

import { useApi } from "./useApi";
import { Banner } from "@/types";
import { useQuery } from "@tanstack/react-query";

export const useBanners = () => {
  const api = useApi();

  return useQuery({
    queryKey: ["banners"],
    queryFn: async () => {
      const { data } = await api.get<Banner[]>("/banners/");
      return data;
    },
  });
};
