"use client";

import { useProducts } from "@/lib/hooks/useProducts";
import { useCategories } from "@/lib/hooks/useCategories";
import { useBanners } from "@/lib/hooks/useBanners";
import ProductsGrid from "@/components/ProductsGrid";
import { useMemo, useState } from "react";
import Image from "next/image";
import Link from "next/link";
import { useUser } from "@clerk/nextjs";

export default function Home() {
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("Όλα");
  const { user } = useUser();

  const { data: products, isLoading, isError } = useProducts();
  const {
    data: categories = [],
    isLoading: categoriesLoading,
    isError: categoriesError,
  } = useCategories();
  const { data: banners = [] } = useBanners();

  // Build categories list with "All" option, sorted by order
  const displayCategories = useMemo(() => {
    const allOption = { name: "Όλα", icon: "📦" };
    const sortedCategories = [...categories].sort((a, b) => {
      const orderA = a.order ?? 999;
      const orderB = b.order ?? 999;
      return orderA - orderB;
    });
    const categoryOptions = sortedCategories.map((cat) => ({
      name: cat.name,
      icon: cat.icon,
      image: cat.image,
    }));
    return [allOption, ...categoryOptions];
  }, [categories]);

  const filteredProducts = useMemo(() => {
    if (!products) return [];

    let filtered = products;

    // filtering by category
    if (selectedCategory !== "Όλα") {
      filtered = filtered.filter((product) => product.category === selectedCategory);
    }

    // filtering by search query
    if (searchQuery.trim()) {
      filtered = filtered.filter((product) =>
        product.name.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }

    return filtered;
  }, [products, selectedCategory, searchQuery]);

  return (
    <div className="min-h-screen bg-[#121212] text-white">
      {/* HEADER */}
      <header className="px-6 pb-4 pt-6">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-white text-3xl font-bold tracking-tight">
              Κατάστημα
            </h1>
            <p className="text-[#B3B3B3] text-sm mt-1">
              Περιήγηση σε όλα τα προϊόντα
            </p>
          </div>

          <div className="flex items-center gap-4">
            {user && (
              <Link
                href="/cart"
                className="bg-[#282828]/50 p-3 rounded-full hover:bg-[#282828] transition-colors relative"
              >
                <span className="text-2xl">🛒</span>
              </Link>
            )}
            <Link
              href={user ? "/profile" : "/sign-in"}
              className="bg-[#282828]/50 p-3 rounded-full hover:bg-[#282828] transition-colors"
            >
              <span className="text-2xl">👤</span>
            </Link>
          </div>
        </div>

        {/* SEARCH BAR */}
        <div className="bg-[#282828] flex items-center px-5 py-4 rounded-2xl">
          <span className="text-[#666] text-xl mr-3">🔍</span>
          <input
            type="text"
            placeholder="Αναζήτηση προϊόντων"
            className="flex-1 bg-transparent text-white text-base outline-none placeholder:text-[#666]"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>

        {/* BANNER */}
        {banners.length > 0 && (
          <div className="mt-4">
            <div className="flex gap-3 overflow-x-auto pb-2 scrollbar-hide">
              {banners.map((banner) => (
                <a
                  key={banner._id}
                  href={banner.linkUrl || "#"}
                  className="flex-shrink-0 rounded-2xl overflow-hidden bg-[#121212]"
                >
                  <Image
                    src={banner.imageUrl}
                    alt={banner.title || "Banner"}
                    width={320}
                    height={160}
                    className="w-80 h-40 object-cover bg-[#121212]"
                    unoptimized
                  />
                </a>
              ))}
            </div>
          </div>
        )}
      </header>

      {/* CATEGORY FILTER */}
      <div className="mb-6">
        {categoriesLoading ? (
          <div className="px-6 py-4 flex items-center justify-center">
            <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-[#FFD700]"></div>
          </div>
        ) : categoriesError ? (
          <div className="px-6 py-4 flex flex-col items-center">
            <p className="text-[#B3B3B3] text-sm mb-2">
              Αποτυχία φόρτωσης κατηγοριών
            </p>
          </div>
        ) : displayCategories.length === 1 ? (
          <div className="px-6 py-4 flex items-center justify-center">
            <p className="text-[#B3B3B3] text-sm">
              Δεν υπάρχουν διαθέσιμες κατηγορίες
            </p>
          </div>
        ) : (
          <div className="flex gap-3 overflow-x-auto px-5 scrollbar-hide">
            {displayCategories.map((category) => {
              const isSelected = selectedCategory === category.name;
              const isAllOption = category.name === "Όλα";
              return (
                <button
                  key={category.name}
                  onClick={() => setSelectedCategory(category.name)}
                  className={`flex-shrink-0 rounded-2xl w-20 h-20 overflow-hidden flex items-center justify-center relative border-2 transition-colors ${
                    isSelected
                      ? "border-[#FFD700]"
                      : "border-transparent"
                  } ${
                    isAllOption
                      ? isSelected
                        ? "bg-[#FFD700]"
                        : "bg-[#282828]"
                      : !category.image
                      ? isSelected
                        ? "bg-[#FFD700]"
                        : "bg-[#282828]"
                      : ""
                  }`}
                >
                  {category.image && !isAllOption ? (
                    <>
                      <Image
                        src={category.image}
                        alt={category.name}
                        fill
                        className="object-cover"
                        unoptimized
                      />
                      {category.icon && (
                        <span className="text-3xl relative z-10">
                          {category.icon}
                        </span>
                      )}
                    </>
                  ) : category.icon ? (
                    <span
                      className={`text-3xl ${
                        isSelected && isAllOption ? "text-[#121212]" : ""
                      }`}
                    >
                      {category.icon}
                    </span>
                  ) : null}
                </button>
              );
            })}
          </div>
        )}
      </div>

      {/* PRODUCTS */}
      <div className="px-6 mb-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-white text-lg font-bold">Προϊόντα</h2>
          <p className="text-[#B3B3B3] text-sm">
            {filteredProducts.length}{" "}
            {filteredProducts.length === 1 ? "προϊόν" : "προϊόντα"}
          </p>
        </div>

        <ProductsGrid
          products={filteredProducts}
          isLoading={isLoading}
          isError={isError}
        />
      </div>
    </div>
  );
}
